function beginRoomLoading(code){const loader=$('roomLoader'),eta=$('roomLoaderEta'),roomCode=$('roomLoaderCode');const started=performance.now(),estimate=roomLoadAverage();if(roomCode)roomCode.textContent=code?`Sala ${String(code).toUpperCase()}`:'';if(loader){loader.hidden=false;loader.classList.remove('done')}setRoomLoadStage('Conectando con la sala…',8);clearInterval(roomLoadTimer);const tick=()=>{const elapsed=performance.now()-started,remaining=Math.max(650,estimate-elapsed),progress=Math.min(90,8+(elapsed/estimate)*78);if(eta)eta.textContent=`Tiempo aproximado: ${Math.max(1,Math.ceil(remaining/1000))} s`;const bar=$('roomLoaderBar');if(bar)bar.style.width=`${progress}%`};tick();roomLoadTimer=setInterval(tick,250);return {started,estimate}}
