function queueVisualSequence(events=[],effects=[],after=Promise.resolve()){const safeEvents=events.filter(e=>!isGoPopup(e));const freshEvents=safeEvents.filter(e=>e&&e.id&&!seenVisuals.has(e.id));const freshEffects=effects.filter(e=>e&&e.id&&!seenBankFx.has(e.id));freshEvents.forEach(e=>seenVisuals.add(e.id));freshEffects.forEach(e=>seenBankFx.add(e.id));const timeline=[...freshEvents.map(value=>({kind:'event',value})),...freshEffects.map(value=>({kind:'bank',value}))].sort((a,b)=>a.value.id-b.value.id);if(!timeline.length)return Promise.resolve(after);visualQueue=visualQueue.then(async()=>{await after;visualBusy=true;renderActions();try{for(const item of timeline){if(item.kind==='event')await renderEvent(item.value);else await showBankFx(item.value)}}finally{visualBusy=false;renderActions()}}).catch(()=>{visualBusy=false;renderActions()});return visualQueue}
