function renderEmojiGrid(container,items,emptyText='Todavía no tienes emojis recientes.'){container.replaceChildren();if(!items.length){container.append(node('span',emptyText,'emoji-placeholder'));return}for(const emoji of items){const b=btn(emoji,()=>insertChatEmoji(emoji));b.setAttribute('aria-label',`Usar ${emoji}`);container.append(b)}}
