function emojisInText(text){try{const seg=new Intl.Segmenter(undefined,{granularity:'grapheme'});return [...seg.segment(text)].map(x=>x.segment).filter(x=>/\p{Extended_Pictographic}/u.test(x)).slice(-6).reverse()}catch{return [...String(text)].filter(x=>/\p{Extended_Pictographic}/u.test(x)).slice(-6).reverse()}}
