function openProfile(){profileDraft={adjust:structuredClone(me.adjust)};$('displayName').value=me.name;$('uploadControls').replaceChildren();for(const [kind,label]of [['avatar','Foto'],['frame','Marco PNG'],['token','Ficha PNG']]){const section=node('section',undefined,'upload-section'),upload=node('input');upload.type='file';upload.accept=kind==='avatar'?'image/png,image/jpeg,image/webp':'image/png';const fileLabel=node('label',label);fileLabel.append(upload);section.append(fileLabel);upload.onchange=async()=>{const file=upload.files[0];if(!file)return;try{if(kind!=='avatar'&&file.type!=='image/png')throw Error('Usa un archivo PNG transparente.');if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8000000)throw Error('Usa una imagen de hasta 8 MB.');const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('No se pudo leer la imagen.'));reader.readAsDataURL(file)});const im=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('No se pudo abrir la imagen.'));im.src=src});const scale=Math.min(1,700/Math.max(im.width,im.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(im.width*scale));canvas.height=Math.max(1,Math.round(im.height*scale));canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);const encoded=canvas.toDataURL(kind==='avatar'?'image/webp':'image/png',.85);if(encoded.length>2100000)throw Error('La imagen sigue siendo demasiado grande. Usa un PNG más pequeño.');profileDraft[kind]=encoded;previewProfile()}catch(e){notify(e.message)}};const sliders=node('div',undefined,'sliders');for(const [key,title,min,max,step]of [['scale','Tamaño',kind==='avatar'?1:.5,3,.01],['x','Horizontal',-70,70,1],['y','Vertical',-70,70,1]]){const label=node('label',title),input=node('input');input.type='range';input.min=min;input.max=max;input.step=step;input.value=profileDraft.adjust[kind][key];input.oninput=()=>{profileDraft.adjust[kind][key]=Number(input.value);previewProfile()};label.append(input);sliders.append(label)}section.append(sliders,btn('Quitar '+label.toLowerCase(),()=>{profileDraft[kind]=null;previewProfile()}));$('uploadControls').append(section)}previewProfile();$('profileDialog').showModal()}
$('displayName').oninput=previewProfile;$('profileOpen').onclick=openProfile;$('fabProfile').onclick=()=>{setFab(false);openProfile()};$('profileClose').onclick=()=>$('profileDialog').close();$('profileForm').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const result=await api('/api/profile',{...profileDraft,name:$('displayName').value});me=result.user;$('profileDialog').close();notify('Perfil guardado.');if(!current)$('welcome').textContent=`Hola, ${me.name}.`}catch(e){notify(e.message)}finally{e.submitter.disabled=false}};
