// The wardrobe is private. Other players only receive links to equipped images.
let wardrobeItems=[],wardrobeSelected=null,wardrobeData=null;
function wardrobeAdjust(){return {scale:Number($('wardrobeScale').value),x:Number($('wardrobeX').value),y:Number($('wardrobeY').value)}}
function wardrobePreview(){const kind=$('wardrobeKind').value,item=wardrobeItems.find(i=>i.id===wardrobeSelected),src=wardrobeData||item?.url,p={...me,assets:{...me.assets,[kind]:src},adjust:{...me.adjust,[kind]:wardrobeAdjust()}};$('wardrobePreview').replaceChildren(kind==='token'?token(p,0):avatar(p))}
function wardrobeEdit(item=null){wardrobeSelected=item?.id||null;wardrobeData=null;$('wardrobeKind').value=item?.kind||'token';$('wardrobeKind').disabled=!!item;$('wardrobeName').value=item?.name||'';$('wardrobeFile').value='';$('wardrobeFile').accept=item?.kind==='avatar'?'image/png,image/jpeg,image/webp':'image/png';$('wardrobeScale').min=item?.kind==='avatar'?1:.5;const a=item?.adjust||{scale:1,x:0,y:0};$('wardrobeScale').value=a.scale;$('wardrobeX').value=a.x;$('wardrobeY').value=a.y;$('wardrobeSave').textContent=item?'Sobrescribir esta imagen':'Guardar nueva';$('wardrobeHint').textContent=item?'Puedes cambiar el nombre, el encuadre o subir otra imagen. Si está equipada, el cambio también se aplica a tu perfil.':'Guardar no cambia lo que llevas equipado. Después pulsa Equipar.';wardrobePreview()}
function renderWardrobe(){$('wardrobeCount').textContent=`${wardrobeItems.length} de 20 imágenes guardadas`;$('wardrobeItems').replaceChildren();for(const item of wardrobeItems){const card=node('div',undefined,'wardrobe-item'),preview=node('div',undefined,'wardrobe-thumb'),im=node('img');im.src=item.url;im.alt=item.name;preview.append(im);card.append(preview,node('strong',item.name),node('small',({avatar:'Foto',frame:'Marco',token:'Ficha'})[item.kind]));const equipped=me.assetIds?.[item.kind]===item.id;card.append(btn(equipped?'Equipada ✓':'Equipar',()=>wardrobeAction('equip',item),equipped),btn('Editar / reemplazar',()=>wardrobeEdit(item)),btn('Borrar',()=>{if(confirm(`¿Borrar “${item.name}” de tu armario?${equipped?' También se quitará de tu perfil.':''}`))wardrobeAction('delete',item)},false,'danger'));$('wardrobeItems').append(card)}if(!wardrobeItems.length)$('wardrobeItems').append(node('p','Todavía no guardaste imágenes. Empieza con tu primera ficha.'))}
async function wardrobeAction(type,item){try{const r=await api('/api/wardrobe/'+type,{id:item.id});me=r.user;if(r.items)wardrobeItems=r.items;renderWardrobe();if(type==='delete'&&wardrobeSelected===item.id)wardrobeEdit();else wardrobePreview();notify(type==='equip'?'Imagen equipada.':'Imagen borrada.')}catch(e){notify(e.message)}}
async function openWardrobe(){try{const r=await api('/api/wardrobe');wardrobeItems=r.items;renderWardrobe();wardrobeEdit();$('wardrobeDialog').showModal()}catch(e){notify(e.message)}}
$('wardrobeOpen').onclick=openWardrobe;$('fabWardrobe').onclick=()=>{setFab(false);openWardrobe()};
$('wardrobeClose').onclick=()=>$('wardrobeDialog').close();$('wardrobeNew').onclick=()=>wardrobeEdit();
$('wardrobeKind').onchange=()=>{wardrobeData=null;$('wardrobeFile').value='';$('wardrobeFile').accept=$('wardrobeKind').value==='avatar'?'image/png,image/jpeg,image/webp':'image/png';$('wardrobeScale').min=$('wardrobeKind').value==='avatar'?1:.5;$('wardrobeScale').value=1;wardrobePreview()};
for(const id of ['wardrobeScale','wardrobeX','wardrobeY'])$(id).oninput=wardrobePreview;
$('wardrobeFile').onchange=async()=>{const file=$('wardrobeFile').files[0];if(!file)return;const kind=$('wardrobeKind').value;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8000000)throw Error('Usa una imagen de hasta 8 MB.');if(kind!=='avatar'&&file.type!=='image/png')throw Error('Los marcos y fichas deben ser PNG.');const url=URL.createObjectURL(file);try{const im=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('No se pudo abrir la imagen.'));im.src=url});const scale=Math.min(1,700/Math.max(im.width,im.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(im.width*scale));canvas.height=Math.max(1,Math.round(im.height*scale));canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);const data=canvas.toDataURL(kind==='avatar'?'image/webp':'image/png',.85);if(data.length>2100000)throw Error('Usa una imagen más pequeña.');wardrobeData=data;wardrobePreview()}finally{URL.revokeObjectURL(url)}}catch(e){notify(e.message)}};
$('wardrobeForm').onsubmit=async e=>{e.preventDefault();$('wardrobeSave').disabled=true;try{if(!wardrobeSelected&&!wardrobeData)throw Error('Primero sube una imagen.');const r=await api('/api/wardrobe/save',{id:wardrobeSelected,kind:$('wardrobeKind').value,name:$('wardrobeName').value,adjust:wardrobeAdjust(),...(wardrobeData?{data:wardrobeData}:{})});me=r.user;wardrobeItems=r.items;renderWardrobe();wardrobeEdit(wardrobeItems.find(i=>i.id===r.id));notify('Guardado en tu armario.')}catch(e){notify(e.message)}finally{$('wardrobeSave').disabled=false}};
// Reconcile state while a room is open. No background requests outside a room.
